  for (const [course, prerequisite] of input.prerequisites) {
    outgoing[prerequisite].push(course);
  }
  const active = new Set(), completed = new Set();
  function cycle(course) {
    if (active.has(course)) return true;
    if (completed.has(course)) return false;
    active.add(course);
    for (const next of outgoing[course]) {
      active.add(next);
      if (cycle(next)) return true;
